jQuery(function($){window.SimpleBasket=window.SimpleBasket||{};SimpleBasket.getTime=function(callback){jQuery.ajax({url:SimpleBasket.ajaxurl,type:"POST",data:{action:"getTime",nonce:SimpleBasket.nonce},success:function(data){if(callback)callback(data)}})};SimpleBasket.getData=function(callback){jQuery.ajax({url:SimpleBasket.ajaxurl,type:"POST",data:{action:"getData",nonce:SimpleBasket.nonce},success:function(data){if(callback)callback(data)}})};SimpleBasket.add=function(id,callback){if(!id)return;jQuery.ajax({url:SimpleBasket.ajaxurl,type:"POST",data:{action:"add",nonce:SimpleBasket.nonce,id:id},success:function(data){if(callback)callback(data)}})};SimpleBasket.remove=function(id,callback){if(!id)return;jQuery.ajax({url:SimpleBasket.ajaxurl,type:"POST",data:{action:"remove",nonce:SimpleBasket.nonce,id:id},success:function(data){if(callback)callback(data)}})};SimpleBasket.updateItem=function(id,quantity,callback){if(!id)return;var quo=parseInt(quantity,10);if(isNaN(quo)||quo<0)quo=0;jQuery.ajax({url:SimpleBasket.ajaxurl,type:"POST",data:{action:"update",nonce:SimpleBasket.nonce,id:id,quo:quo},success:function(data){if(callback)callback(data)}})};SimpleBasket.updateButtonsState=function(basket){var limit=parseInt(SimpleBasket.itemLimit||0,10)||0,normalText=SimpleBasket.buyNowCaption||"Buy",limitText=SimpleBasket.buyNowLimitCaption||"Added";if(!basket||!basket.items){$(".simple-basket-buy-now").each(function(){var $btn=$(this);if(!$btn.data("original-text"))$btn.data("original-text",$btn.text());$btn.removeClass("simple-basket-buy-now--limit").prop("disabled",false).text($btn.data("original-text")||normalText)});return}var counts={};$.each(basket.items,function(id,item){if(item&&item.SIMPLE_BASKET_QUO)counts[id]=parseInt(item.SIMPLE_BASKET_QUO,10)||0});$(".simple-basket-buy-now").each(function(){var $btn=$(this),id=$btn.data("product-id");if(!id)return;if(!$btn.data("original-text"))$btn.data("original-text",$btn.text());var quo=counts[id]||0;if(limit>0&&quo>=limit){$btn.addClass("simple-basket-buy-now--limit").prop("disabled",false).text(limitText)}else{$btn.removeClass("simple-basket-buy-now--limit").prop("disabled",false).text($btn.data("original-text")||normalText)}})};SimpleBasket.getCountFromBasket=function(basket){var total=0;if(!basket||!basket.items)return 0;$.each(basket.items,function(id,item){if(item&&item.SIMPLE_BASKET_QUO&&item.SIMPLE_BASKET_QUO>0)total+=parseInt(item.SIMPLE_BASKET_QUO,10)||0});return total};SimpleBasket.updateCountView=function(basket){var total=SimpleBasket.getCountFromBasket(basket);if(total>0){$(".simple-basket-count").text(total);$(".btn-basket").addClass("not_empty-basket")}else{$(".simple-basket-count").text("0");$(".btn-basket").removeClass("not_empty-basket")}};SimpleBasket.refreshCount=function(){SimpleBasket.getData(function(basket){SimpleBasket.updateCountView(basket);SimpleBasket.updateButtonsState(basket)})};SimpleBasket.updateBasketDataFromDom=function(){var $basketFormWrapper=$("#basketForm");if(!$basketFormWrapper.length)return;var items=[];$basketFormWrapper.find("table.basket tbody tr").each(function(){var $row=$(this),id=$row.data("product-id");if(!id)return;var title=$.trim($row.find("td.title").text()),quantity=0,$qtyInput=$row.find('.quantity input[type="number"]');if($qtyInput.length){quantity=parseInt($qtyInput.val(),10)||0}else{var $quoCell=$row.find("td.quo");if($quoCell.length){var raw=$quoCell.data("value");if(typeof raw==="undefined"||raw===null||raw==="")raw=$quoCell.text();quantity=parseInt(raw,10)||0}}var price=null,$priceCell=$row.find("td.price");if($priceCell.length){var rawPrice=$priceCell.data("value");if(typeof rawPrice!=="undefined"){price=parseFloat(rawPrice);if(isNaN(price))price=null}}items.push({id:id,title:title,quantity:quantity,price:price})});var payload={items:items};$basketFormWrapper.attr("data-basket",JSON.stringify(payload))};$(document).on("click",".basketForm .quantity-button",function(e){e.preventDefault();var $btn=$(this),$wrapper=$btn.closest(".quantity"),$input=$wrapper.find('input[type="number"]');if(!$input.length)return;var current=parseInt($input.val(),10);if(isNaN(current))current=0;var min=parseInt($input.attr("min"),10);if(isNaN(min))min=0;if($btn.hasClass("quantity-up"))current+=1;else if($btn.hasClass("quantity-down"))current-=1;if(current<min)current=min;$input.val(current);$input.trigger("change")});$(document).on("change",".basketForm .quantity input[type=\"number\"]",function(){var $input=$(this),$row=$input.closest("tr[data-product-id]"),id=$row.data("product-id");if(!id){SimpleBasket.updateBasketDataFromDom();return}var qty=parseInt($input.val(),10);if(isNaN(qty)||qty<0){qty=0;$input.val(qty)}SimpleBasket.updateItem(id,qty,function(basket){SimpleBasket.updateCountView(basket);SimpleBasket.updateButtonsState(basket);SimpleBasket.updateBasketDataFromDom()})});$(document).on("click",".simple-basket-buy-now",function(e){var $link=$(this),id=$link.data("product-id");if(!id)return;e.preventDefault();if($link.hasClass("simple-basket-buy-now--limit")){SimpleBasket.remove(id,function(basket){SimpleBasket.updateCountView(basket);SimpleBasket.updateButtonsState(basket)})}else{SimpleBasket.add(id,function(basket){SimpleBasket.updateCountView(basket);SimpleBasket.updateButtonsState(basket)})}$(".btn-basket").addClass("animate-me");setTimeout(function(){$(".btn-basket").removeClass("animate-me")},1e3)});SimpleBasket.refreshCount();if(jQuery("#basketForm").length){SimpleBasket.updateBasketDataFromDom()}}); 